package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat._clearFormats().
 * Since _clearFormats is protected, we use a subclass to expose it for testing.
 */
public class StdDateFormat__clearFormats_TriageGen1Test {

    /**
     * A test subclass to expose the protected method _clearFormats.
     */
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(TimeZone tz, Locale loc) {
            super(tz, loc);
        }

        @Override
        public void _clearFormats() {
            super._clearFormats();
        }

        // Helper to check if internal formats are null via reflection or side effects.
        // Since we cannot access private fields directly without reflection, 
        // we verify the effect by checking if the object's behavior changes 
        // (i.e., it re-initializes formats upon next use).
        public boolean areFormatsNull() throws Exception {
            java.lang.reflect.Field f1 = StdDateFormat.class.getDeclaredField("_formatRFC1123");
            java.lang.reflect.Field f2 = StdDateFormat.class.getDeclaredField("_formatISO8601");
            java.lang.reflect.Field f3 = StdDateFormat.class.getDeclaredField("_formatISO8601_z");
            java.lang.reflect.Field f4 = StdDateFormat.class.getDeclaredField("_formatPlain");

            f1.setAccessible(true);
            f2.setAccessible(true);
            f3.setAccessible(true);
            f4.setAccessible(true);

            return f1.get(this) == null && 
                   f2.get(this) == null && 
                   f3.get(this) == null && 
                   f4.get(this) == null;
        }
    }

    @Test
    public void testClearFormatsSetsInternalFieldsToNull() throws Exception {
        TestableStdDateFormat dateFormat = new TestableStdDateFormat();

        // First, trigger the creation of formats by performing some operations
        Date now = new Date();
        dateFormat.format(now, new StringBuffer());
        dateFormat.parse("2023-10-27T10:00:00Z");
        dateFormat.parse("Fri, 27 Oct 2023 10:00:00 GMT");

        // Ensure they are not null before clearing (via reflection check)
        assertFalse("Formats should be initialized after use", dateFormat.areFormatsNull());

        // Execute the method under test
        dateFormat._clearFormats();

        // Verify that all internal format fields are now null
        assertTrue("All internal format fields should be null after _clearFormats()", 
                   dateFormat.areFormatsNull());
    }

    @Test
    public void testClearFormatsDoesNotAffectTimeZoneOrLocale() throws Exception {
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;
        TestableStdDateFormat dateFormat = new TestableStdDateFormat(tz, locale);

        // Initialize formats
        dateFormat.format(new Date(), new StringBuffer());

        // Execute clear
        dateFormat._clearFormats();

        // Verify state is preserved
        assertEquals(tz, dateFormat.getTimeZone());
        assertEquals(locale, dateFormat.getLocale());
        assertTrue(dateFormat.areFormatsNull());
    }

    @Test
    public void testClearFormatsMultipleTimes() throws Exception {
        TestableStdDateFormat dateFormat = new TestableStdDateFormat();

        // Call multiple times to ensure no exceptions (like NullPointerException) occur
        dateFormat._clearFormats();
        assertTrue(dateFormat.areFormatsNull());

        dateFormat._clearFormats();
        assertTrue(dateFormat.areFormatsNull());
    }
}
